function GetGoldenVortex()
	local X, P, Y = next, workspace.ActiveFishingSpots:GetChildren()
	local H, C = 1 / 0
	for J, F in X, P, Y do
		if F.Name == "GoldenVortex" then
			J = (game.Players.LocalPlayer.Character.HumanoidRootPart.Position - F.Position).Magnitude
			if J < H then
				H, C = J, F
			end
		end
	end
	return C
end
