function DetectQuestSeaDragon()
	local V, y, P = next, game:GetService("Workspace").Enemies:GetChildren()
	for Y, Y in V, y, P do
		if
			Y:FindFirstChild("Engine")
			and (Y:FindFirstChild("Health"))
			and Y.Health.Value > 0
