function DetectIslandKitsune()
	if
		game.workspace.Map:FindFirstChild("KitsuneIsland")
		and workspace.Map.KitsuneIsland.ShrineDialogPart.ProximityPrompt.Enabled
	then
		return true
	end
end
function AutoSpawnKitsune()
	local y, P = game.Lighting.ClockTime, checkboat()
	if Settings["Hop Server Kitsune Island"] then
		local Y = CheckMoon()
		if
			not (
				Y == "Full Moon" and math.floor(18 - y) <= 5 and math.floor(18 - y) >= 0
				or Y == "Next Night"
				or Y == "Full Moon" and y <= 5 and math.floor(5 - y) >= 11
			)
		then
			HopServer()
			return
		end
	end
	if not P then
		local Y = CFrame.new(-13.488054275512695, 10.311711311340332, 2927.692)
		Y = if game.PlaceId == getgenv().CheckPlaceId
			then (CFrame.new(-16204.0810546875, 9.0863618850708, 479.2259521484375))
			else Y
		if (Y.Position - t.Character.HumanoidRootPart.Position).Magnitude > 8 then
			toTarget(Y)
		else
			local Y = Settings["Select Boat"]
			if not Y then
				WarnOnce("SelectBoat", "Chon thuyen o Sea Event > Select Boat truoc da.")
				return
			end
			local H = Y == "Brigade"
			game:GetService("ReplicatedStorage").Remotes.CommF_
				:InvokeServer("BuyBoat", if H or Y == "GrandBrigade" then "Pirate" .. Y else Y)
			task.wait(0.1)
		end
		return
	end
	NoclipBoat(P)
	local Y = P.WorldPivot.Y
	local H = CFrame.new(-32975.9921875, Y, 25963.7109375) * CFrame.new(0, 0, 1000)
	if CheckMoon() == "Full Moon" and math.floor(18 - y) <= 0 then
		if (P.VehicleSeat.Position - H.Position).Magnitude > 200 then
			if not t.Character.Humanoid.Sit then
				toTarget(P.VehicleSeat.CFrame)
			else
				manageTween(P.VehicleSeat, H, 350, "TweenBoat")
			end
		elseif not t.Character.Humanoid.Sit then
			toTarget(P.VehicleSeat.CFrame)
		end
	else
		if (P.VehicleSeat.Position - H.Position).Magnitude > 200 then
			manageTween(P.VehicleSeat, H, 350, "TweenBoat")
		end
		toTarget(H * CFrame.new(0, 2000, 0))
	end
end
function DetectSoulEmber()
	local y, P, Y = next, game.Workspace:GetChildren()
	for H, H in y, P, Y do
		if H.Name == "EmberTemplate" and (H:FindFirstChild("Part")) then
			return H
		end
	end
end
function CollectSoulEmber()
	local y = DetectSoulEmber()
	if y then
		if t:DistanceFromCharacter(y.Part.Position) > 100 then
			toTarget(y.Part.CFrame)
		else
			t.Character.HumanoidRootPart.CFrame = y.Part.CFrame
		end
	else
		toTarget(game.workspace._WorldOrigin.Locations["Kitsune Island"].CFrame)
	end
end
function AutoSummonAzureEmber()
	if
		not game:GetService("Players").LocalPlayer.PlayerGui.Main.TopHUDList.RaidTimer.Visible
		and (DetectIslandKitsune())
	then
		if t:DistanceFromCharacter(game.Workspace.Map.KitsuneIsland.ShrineInactive.WorldPivot.Position) >= 10 then
			toTarget(game.Workspace.Map.KitsuneIsland.ShrineInactive.WorldPivot)
		else
			game:GetService("ReplicatedStorage").Modules.Net:FindFirstChild("RE/TouchKitsuneStatue"):FireServer()
			wait(5)
		end
	end
end
function TradeAzureEmber()
	if
		CheckCountItem("Azure Ember", tonumber(Settings["Values Azure Ember"]))
		and game:GetService("Players").LocalPlayer.PlayerGui.Main.TopHUDList.RaidTimer.Visible
	then
		game:GetService("ReplicatedStorage").Modules.Net:FindFirstChild("RF/KitsuneStatuePray"):InvokeServer()
		wait(5)
	end
end
spawn(function()
	repeat
		wait(0.15)
	until Settings["Teleport To Kitsune Island"]
		or Settings["Auto Spawn Kitsune Island"]
		or Settings["Auto Collect Soul Ember"]
		or Settings["Auto Trade Azure Ember"]
	while task.wait(0.1) do
		pcall(function()
			if Settings["Teleport To Kitsune Island"] then
				if game.workspace._WorldOrigin.Locations:FindFirstChild("Kitsune Island") then
					toTarget(game.workspace._WorldOrigin.Locations["Kitsune Island"].CFrame)
				end
			end
			if Settings["Auto Spawn Kitsune Island"] then
				pcall(function()
					if not DetectIslandKitsune() then
						AutoSpawnKitsune()
					end
				end)
			end
			if Settings["Auto Collect Soul Ember"] then
				if game:GetService("Players").LocalPlayer.PlayerGui.Main.TopHUDList.RaidTimer.Visible then
					CollectSoulEmber()
				end
			end
			if Settings["Auto Summon Soul Ember"] then
				AutoSummonAzureEmber()
			end
			if Settings["Auto Trade Azure Ember"] then
				TradeAzureEmber()
			end
		end)
	end
end)
-- Farming Multi: mantém o seletor multi-jogador no mesmo formato usado pelos outros seletores do hub.
do
local FarmingMultiSeaEvent = {}
FarmingMultiSeaEvent.Section = SeaEventTab.CreateSection("Farming Multi")
FarmingMultiSeaEvent.Dropdown = FarmingMultiSeaEvent.Section.CreateDropdown(
	{
		Title = "Select Player Multi Sea Event",
		List = PrepareMultiSelectList(DetectNamePlayerMulti(), Settings["Select Player Multi Sea Event"]),
		Search = true,
		Selected = true,
		Default = Settings["Select Player Multi Sea Event"] or nil,
	},
	function(value, state)
		-- O dropdown fornece o nome e o estado da opção alterada; gravar ambos é essencial
		-- para que getSelectedPlayerNames consiga identificar os jogadores marcados.
		SaveSettings("Select Player Multi Sea Event", value, state)
	end
)
FarmingMultiSeaEvent.Section.CreateButton({ Title = "Refresh Player" }, function()
	-- Atualiza somente os jogadores disponíveis; o save em Settings é preservado.
	FarmingMultiSeaEvent.Dropdown:GetNewList(PrepareMultiSelectList(DetectNamePlayerMulti(), Settings["Select Player Multi Sea Event"]))
end)
FarmingMultiSeaEvent.Section.CreateToggle(
	{
		Title = "Auto Multi Sea Event",
		Desc = "Wait for selected players to sit in your boat, move forward 650 studs, then start Sea Event.",
		Default = Settings["Auto Multi Sea Event"] or false,
	},
	function(enabled)
		SaveSettings("Auto Multi Sea Event", enabled)
		getgenv().MultiSeaEventRunId = (getgenv().MultiSeaEventRunId or 0) + 1
		local runId = getgenv().MultiSeaEventRunId

		if not enabled then
			pcall(function() local b=checkboat() local s=b and b:FindFirstChild("VehicleSeat", true) if s then s.ThrottleFloat=0 s.Throttle=0 end end)
			return
		end

		task.spawn(function()
			local Players = game:GetService("Players")
			local VIM = game:GetService("VirtualInputManager")
			local lastWaitNotice = 0
			local lastBoatBuyAttempt = 0

			local function getSelectedPlayerNames()
				-- Usa o mesmo formato salvo pelo dropdown original do hub:
				-- Settings["Select Player Multi Sea Event"][playerName] = true/false.
				-- Também aceita listas de nomes, sem apagar o save existente.
				local selected = Settings["Select Player Multi Sea Event"]
				local names, seen = {}, {}
				if type(selected) ~= "table" then return names end
				for key, value in pairs(selected) do
					local playerName
					if type(key) == "string" and value == true then
						playerName = key
					elseif type(key) == "number" and type(value) == "string" then
						playerName = value
					end
					if playerName and playerName ~= t.Name and not seen[playerName] and Players:FindFirstChild(playerName) then
						seen[playerName] = true
						table.insert(names, playerName)
					end
				end
				table.sort(names)
				return names
			end

			local function areSelectedPlayersSeatedInBoat(boat)
				local names = getSelectedPlayerNames()
				if #names == 0 then
					return false, {"Select Player Multi Sea Event"}
				end
				local missing = {}
				for _, playerName in ipairs(names) do
					local player = Players:FindFirstChild(playerName)
					if not player or player == t then
						if playerName ~= t.Name then table.insert(missing, playerName) end
					else
						local character = player.Character
						local humanoid = character and character:FindFirstChildOfClass("Humanoid")
						local seatPart = humanoid and humanoid.SeatPart
						if not seatPart or not seatPart:IsDescendantOf(boat) then
							table.insert(missing, playerName)
						end
					end
				end
				return #missing == 0, missing
			end

			local movementCompleted = false
			while Settings["Auto Multi Sea Event"] and getgenv().MultiSeaEventRunId == runId do
				local selectedNames = getSelectedPlayerNames()
				if #selectedNames == 0 then
					if tick() - lastWaitNotice >= 5 then
						lastWaitNotice = tick()
						pcall(function() A.CreateNoti({ Title = "Nexora Hub", Desc = "Select players in Select Player Multi Sea Event first", ShowTime = 5 }) end)
					end
					task.wait(1)
					continue
				end

				local boatOk, boat = pcall(checkboat)
				if boatOk and (not boat or not boat.Parent) and not movementCompleted then
					-- Buy only after the user has selected players and a boat type.
					if Settings["Select Boat"] and tick() - lastBoatBuyAttempt >= 5 then
						lastBoatBuyAttempt = tick()
						pcall(function() BuyBoatAndTeleBoat(true) end)
					end
					task.wait(0.5)
					boatOk, boat = pcall(checkboat)
				end

				if boatOk and boat and boat.Parent and not movementCompleted then
					local seat = boat:FindFirstChild("VehicleSeat", true)
					local character = t.Character
					local humanoid = character and character:FindFirstChildOfClass("Humanoid")
					if seat and seat:IsA("VehicleSeat") and humanoid and humanoid.SeatPart ~= seat then
						-- Go directly to the vehicle seat; once seated, keep waiting for the selected players.
						pcall(function() toTarget(seat.CFrame) end)
						task.wait(0.5)
					end

					local seated, missingPlayers = areSelectedPlayersSeatedInBoat(boat)
					if not seated then
						if tick() - lastWaitNotice >= 5 then
							lastWaitNotice = tick()
							local desc = "Waiting for selected players to sit in the boat"
							if #missingPlayers > 0 and missingPlayers[1] ~= "Select Player Multi Sea Event" then
								desc = "Waiting for: " .. table.concat(missingPlayers, ", ")
							end
							pcall(function() A.CreateNoti({ Title = "Nexora Hub", Desc = desc, ShowTime = 5 }) end)
						end
					else
						local currentCharacter = t.Character
						local currentHumanoid = currentCharacter and currentCharacter:FindFirstChildOfClass("Humanoid")
						if currentHumanoid and currentHumanoid.SeatPart == seat then
							local startPosition = seat.Position
							local movementValid = true
							-- V10: Usa lógica nativa do Roblox igual ao Multi Find Prehistoric Island (ThrottleFloat) - funciona mobile e PC sem W
							local function SetMultiSeaForward(vSeat, enabled)
								if not vSeat or not vSeat.Parent then return end
								pcall(function() vSeat.ThrottleFloat = enabled and 1 or 0 end)
								pcall(function() vSeat.Throttle = enabled and 1 or 0 end)
							end
							SetMultiSeaForward(seat, true)
							while Settings["Auto Multi Sea Event"] and getgenv().MultiSeaEventRunId == runId and seat.Parent and (seat.Position - startPosition).Magnitude < 650 do
								local stillSeated = areSelectedPlayersSeatedInBoat(boat)
								local charNow = t.Character
								local humNow = charNow and charNow:FindFirstChildOfClass("Humanoid")
								-- V10: Espera robusta nativa
								if not stillSeated or not humNow or humNow.SeatPart ~= seat then
									SetMultiSeaForward(seat, false)
									pcall(function() A.CreateNoti({ Title = "Nexora Hub", Desc = "Player saiu do SEAT, pausando...", ShowTime = 3 }) end)
									repeat
										task.wait(0.5)
										stillSeated = areSelectedPlayersSeatedInBoat(boat)
										local charCheck = t.Character
										local humCheck = charCheck and charCheck:FindFirstChildOfClass("Humanoid")
										if humCheck and humCheck.SeatPart ~= seat then
											stillSeated = false
										end
									until (stillSeated and Settings["Auto Multi Sea Event"] and getgenv().MultiSeaEventRunId == runId) or not Settings["Auto Multi Sea Event"] or getgenv().MultiSeaEventRunId ~= runId or not seat.Parent
									if not Settings["Auto Multi Sea Event"] or getgenv().MultiSeaEventRunId ~= runId or not seat.Parent then
										movementValid = false
										break
									end
									pcall(function() A.CreateNoti({ Title = "Nexora Hub", Desc = "Todos de volta no SEAT, continuando...", ShowTime = 3 }) end)
									SetMultiSeaForward(seat, true)
									startPosition = seat.Position
								end
								SetMultiSeaForward(seat, true) -- reaplica continuamente
								task.wait()
							end
							SetMultiSeaForward(seat, false)
							if movementValid and seat.Parent and (seat.Position - startPosition).Magnitude >= 650 and areSelectedPlayersSeatedInBoat(boat) and Settings["Auto Multi Sea Event"] and getgenv().MultiSeaEventRunId == runId then
								movementCompleted = true
								SaveSettings("Auto Sea Event", true)
								task.spawn(function()
									while Settings["Auto Multi Sea Event"] and Settings["Auto Sea Event"] and getgenv().MultiSeaEventRunId == runId do
										pcall(AutoSeabeast)
										task.wait(0.1)
									end
								end)
							end
						end
					end
				end
				task.wait(0.25)
			end
			pcall(function() VIM:SendKeyEvent(false, Enum.KeyCode.W, false, game) end)
		end)
	end
)

