function CountZombie(g)
	local R = 0
	for m, m in pairs(game.workspace.Enemies:GetChildren()) do
		R = if m.Name == "Living Zombie" and m.Humanoid.Health > 0 then if not g then R + 1 else R else R
	end
	return R
end
