function DetectSwordUnlock()
	local g, f, R = next, B()
	local m, l = 0
	for S, S in g, f, R do
		if S.Type == "Sword" and 600 > S.Mastery then
			if m < S.Rarity then
				m, l = S.Rarity, S.Name
			end
		end
	end
	return l
end
