function DetectGunUnlock()
	local g, f, R = next, B()
	local m, l = 0
	for Q, Q in g, f, R do
		if Q.Type == "Gun" and 600 > Q.Mastery then
			if m < Q.Rarity then
				m, l = Q.Rarity, Q.Name
			end
		end
	end
	return l
