					toTarget(g.HumanoidRootPart.CFrame * CFrame.new(0, 4, 4))
				else
					local g = game:GetService("ReplicatedStorage")
						:WaitForChild("Modules")
						:WaitForChild("Net")
						:WaitForChild("RF/DragonHunter")
						:InvokeServer(unpack({ [1] = { Context = "Check" } }))
