function IsAutoMultiPrehistoricActive()
	return Settings["Auto Multi Find Prehistoric Island"] == true
end

function GetSelectedMultiPrehistoricPlayers()
	local selected = Settings["Select Player Multi Prehistoric Island"]
	local result = {}
	if type(selected) ~= "table" then
		return result
	end
	for name, enabled in pairs(selected) do
		if enabled == true then
			local player = game:GetService("Players"):FindFirstChild(name)
			if player and player ~= t then
				table.insert(result, player)
			end
		end
	end
	return result
end

function IsSelectedPlayersSeatedInMyBoat()
	-- Recalcula a lista de selecionados a cada chamada; nada fica em cache.
	local selected = GetSelectedMultiPrehistoricPlayers()
	if #selected == 0 then
		return false
	end
	local boat = checkboat()
	if not boat or not boat.Parent then
		return false
	end

	-- O jogador só é considerado dentro do barco quando estiver sentado em um Seat/VehicleSeat que pertença ao barco.
	local function isPlayerInMyBoat(player)
		local character = player and player.Character
		if not character then return false end
		local humanoid = character:FindFirstChildOfClass("Humanoid")
		if not humanoid then return false end
		local seat = humanoid.SeatPart
		return seat ~= nil and (seat:IsA("Seat") or seat:IsA("VehicleSeat")) and seat:IsDescendantOf(boat)
	end

	for _, player in ipairs(selected) do
		if not isPlayerInMyBoat(player) then
			return false
		end
	end
	return true
end

function HandleMultiPrehistoricSelectedSeatExit()
	-- Detecta somente a saída real do SEAT do barco. Não para o barco nem pausa o Multi Find.
	-- Quando ocorre uma saída, o jogador local dá apenas um pulo por saída.
	local selected = GetSelectedMultiPrehistoricPlayers()
	local boat = checkboat()
	if #selected == 0 or not boat or not boat.Parent then
		getgenv().MultiPrehistoricSelectedSeatState = {}
		return
	end

	getgenv().MultiPrehistoricSelectedSeatState = getgenv().MultiPrehistoricSelectedSeatState or {}
	local state = getgenv().MultiPrehistoricSelectedSeatState

	for _, player in ipairs(selected) do
		local character = player and player.Character
		local humanoid = character and character:FindFirstChildOfClass("Humanoid")
		local seat = humanoid and humanoid.SeatPart
		local seatedInBoat = seat ~= nil
			and (seat:IsA("Seat") or seat:IsA("VehicleSeat"))
			and seat:IsDescendantOf(boat)

		local wasSeated = state[player.Name] == true
		if wasSeated and not seatedInBoat then
			local localCharacter = t.Character
			local localHumanoid = localCharacter and localCharacter:FindFirstChildOfClass("Humanoid")
			if localHumanoid and localHumanoid.Parent then
				localHumanoid.Jump = true
			end
			state[player.Name] = false
		elseif seatedInBoat then
			state[player.Name] = true
		else
			state[player.Name] = false
		end
	end

	-- Remove estados de jogadores que deixaram de estar selecionados.
	local selectedNames = {}
	for _, player in ipairs(selected) do
		selectedNames[player.Name] = true
	end
	for name in pairs(state) do
		if not selectedNames[name] then
			state[name] = nil
		end
	end
end

local function SetMultiPrehistoricForward(vehicleSeat, enabled)
	if not vehicleSeat or not vehicleSeat.Parent then return end
	-- Usa exclusivamente o movimento nativo do Roblox pelo VehicleSeat.
	-- Não envia W/VirtualInputManager e funciona tanto no celular quanto no PC.
	pcall(function()
		vehicleSeat.ThrottleFloat = enabled and 1 or 0
	end)
	pcall(function()
		vehicleSeat.Throttle = enabled and 1 or 0
	end)
end

function AutoMultiFindPrehistoric()
	if not Settings["Auto Multi Find Prehistoric Island"] then
		return
	end

	-- Enquanto a Prehistoric Island estiver spawnada, o Multi Find fica totalmente pausado.
	-- Ele não tenta comprar barco, reunir jogadores ou procurar a ilha novamente.
	if workspace.Map:FindFirstChild("PrehistoricIsland") then
		local spawnedBoat = checkboat()
		local spawnedSeat = spawnedBoat and spawnedBoat:FindFirstChild("VehicleSeat", true)
		if spawnedSeat and spawnedSeat:IsA("VehicleSeat") then
			SetMultiPrehistoricForward(spawnedSeat, false)
		end
		getgenv().MultiPrehistoricMovingForward = false
		getgenv().MultiPrehistoricTwoMeterDone = false
		if not getgenv().MultiPrehistoricSpawnNoti then
			getgenv().MultiPrehistoricSpawnNoti = true
			A.CreateNoti({ Title = "Nexora Hub", Desc = "Prehistoric Island Spawned", ShowTime = 5 })
		end
		return
	else
		-- A busca volta a ficar disponível somente depois que a ilha desaparecer.
		getgenv().MultiPrehistoricSpawnNoti = false
	end

	local selected = GetSelectedMultiPrehistoricPlayers()
	if #selected == 0 then
		return
	end

	local boat = checkboat()
	-- Se já existe um barco, mas ele está muito longe do Tiki, não use o barco antigo.
	-- Só compra outro se o jogador local também estiver longe do barco.
	if boat and boat.Parent then
		local boatSeat = boat:FindFirstChild("VehicleSeat", true)
		local tikiPosition = Vector3.new(-16204.0810546875, 9.0863618850708, 479.2259521484375)
		local character = t.Character
		local root = character and character:FindFirstChild("HumanoidRootPart")
		local playerNearBoat = false
		if boatSeat and boatSeat:IsA("VehicleSeat") and root then
			playerNearBoat = (root.Position - boatSeat.Position).Magnitude <= 350
		end
		if boatSeat and boatSeat:IsA("VehicleSeat") and (boatSeat.Position - tikiPosition).Magnitude >= 4000 and not playerNearBoat then
			getgenv().MultiPrehistoricTwoMeterDone = false
			getgenv().MultiPrehistoricWaitingNoti = false
			getgenv().MultiPrehistoricWaitingNotiTime = nil
			getgenv().MultiPrehistoricSpawnNoti = false
			getgenv().MultiPrehistoricMovingForward = false
			if getgenv().TweenBoat then
				getgenv().TweenBoat:Pause()
				getgenv().TweenBoat:Cancel()
			end
			if not root then
				return
			end
			local boatShop = CFrame.new(-16204.0810546875, 9.0863618850708, 479.2259521484375)
			if game.PlaceId ~= getgenv().CheckPlaceId then
				boatShop = CFrame.new(-13.488054275512695, 10.311711311340332, 2927.692)
			end
			if (boatShop.Position - root.Position).Magnitude > 8 then
				toTarget(boatShop)
				return
			end
			BuyMultiPrehistoricBoat()
			task.wait(0.1)
			return
		end
	end

	if not boat then
		getgenv().MultiPrehistoricTwoMeterDone = false
		local character = t.Character
		local root = character and character:FindFirstChild("HumanoidRootPart")
		if not root then
			return
		end
		local boatShop = CFrame.new(-16204.0810546875, 9.0863618850708, 479.2259521484375)
		if game.PlaceId ~= getgenv().CheckPlaceId then
			boatShop = CFrame.new(-13.488054275512695, 10.311711311340332, 2927.692)
		end
		if (boatShop.Position - root.Position).Magnitude > 8 then
			toTarget(boatShop)
			return
		end
		BuyMultiPrehistoricBoat()
		task.wait(0.1)
		return
	end

	local vehicleSeat = boat:FindFirstChild("VehicleSeat", true)
	if not vehicleSeat or not vehicleSeat:IsA("VehicleSeat") then
		return
	end

	-- Verifica a saída do SEAT dos jogadores selecionados. Se alguém sair,
	-- faz somente um pulo do jogador local; o barco continua funcionando.
	HandleMultiPrehistoricSelectedSeatExit()

	if not IsSelectedPlayersSeatedInMyBoat() then
		local missingPlayers = {}
		local selectedNow = GetSelectedMultiPrehistoricPlayers()
		local currentBoat = checkboat()
		if currentBoat and currentBoat.Parent then
			for _, player in ipairs(selectedNow) do
				local character = player.Character
				local humanoid = character and character:FindFirstChildOfClass("Humanoid")
				local seat = humanoid and humanoid.SeatPart
				local inBoat = seat and (seat:IsA("Seat") or seat:IsA("VehicleSeat")) and seat:IsDescendantOf(currentBoat) or false
				if not inBoat then
					table.insert(missingPlayers, player.Name)
				end
			end
		else
			for _, player in ipairs(selectedNow) do
				table.insert(missingPlayers, player.Name)
			end
		end
		local now = tick()
		if not getgenv().MultiPrehistoricWaitingNoti or not getgenv().MultiPrehistoricWaitingNotiTime or now - getgenv().MultiPrehistoricWaitingNotiTime >= 2 then
			getgenv().MultiPrehistoricWaitingNoti = true
			getgenv().MultiPrehistoricWaitingNotiTime = now
			local desc = "Waiting for selected players to sit in the boat"
			if #missingPlayers > 0 then
				desc = "Waiting for: " .. table.concat(missingPlayers, ", ")
			end
			A.CreateNoti({ Title = "Nexora Hub", Desc = desc, ShowTime = 2 })
		end
		local localHumanoid = t.Character and t.Character:FindFirstChildOfClass("Humanoid")
		if localHumanoid and not localHumanoid.Sit then
			toTarget(vehicleSeat.CFrame)
		end
		return
	end

	local localHumanoid = t.Character and t.Character:FindFirstChildOfClass("Humanoid")
	if not localHumanoid or localHumanoid.SeatPart ~= vehicleSeat then
		getgenv().MultiPrehistoricMovingForward = false
		SetMultiPrehistoricForward(vehicleSeat, false)
		toTarget(vehicleSeat.CFrame)
		return
	end

	-- Só começa o avanço quando todos os selecionados estiverem realmente sentados.
	if not getgenv().MultiPrehistoricTwoMeterDone then
		getgenv().MultiPrehistoricMovingForward = true
		local startPosition = vehicleSeat.Position

		-- Dá 1 segundo para o VehicleSeat/canhão estabilizar.
		task.wait(1)

		-- Revalida tudo depois da espera.
		if workspace.Map:FindFirstChild("PrehistoricIsland") then
			SetMultiPrehistoricForward(vehicleSeat, false)
			getgenv().MultiPrehistoricMovingForward = false
			return
		end
		HandleMultiPrehistoricSelectedSeatExit()
		localHumanoid = t.Character and t.Character:FindFirstChildOfClass("Humanoid")
		if not localHumanoid or localHumanoid.SeatPart ~= vehicleSeat then
			SetMultiPrehistoricForward(vehicleSeat, false)
			getgenv().MultiPrehistoricMovingForward = false
			return
		end

		-- Mantém o movimento nativo do Roblox para frente até 650 studs, sem limite artificial de tempo.
		SetMultiPrehistoricForward(vehicleSeat, true)

		while Settings["Auto Multi Find Prehistoric Island"] and vehicleSeat.Parent do
			-- Verifica a saída do SEAT continuamente. Se alguém sair, faz somente um pulo único.
			HandleMultiPrehistoricSelectedSeatExit()
			-- Reaplica o movimento nativo continuamente para manter o avanço até os 650 studs.
			SetMultiPrehistoricForward(vehicleSeat, true)
			if workspace.Map:FindFirstChild("PrehistoricIsland") then
				break
			end
			local currentHumanoid = t.Character and t.Character:FindFirstChildOfClass("Humanoid")
			if not currentHumanoid or currentHumanoid.SeatPart ~= vehicleSeat then
				break
			end
			if (vehicleSeat.Position - startPosition).Magnitude >= 650 then
				getgenv().MultiPrehistoricTwoMeterDone = true
				break
			end
			task.wait()
		end

		SetMultiPrehistoricForward(vehicleSeat, false)
		getgenv().MultiPrehistoricMovingForward = false

		-- Se saiu do barco ou algum selecionado saiu, não chama a caça da ilha.
		local currentHumanoid = t.Character and t.Character:FindFirstChildOfClass("Humanoid")
		if workspace.Map:FindFirstChild("PrehistoricIsland") then
			getgenv().MultiPrehistoricTwoMeterDone = false
			return
		end
		if not currentHumanoid or currentHumanoid.SeatPart ~= vehicleSeat then
			getgenv().MultiPrehistoricTwoMeterDone = false
			return
		end
		if not getgenv().MultiPrehistoricTwoMeterDone then
			return
		end
	end

	-- Nunca chama AutoFind enquanto o dono do barco estiver fora do VehicleSeat.
	local finalHumanoid = t.Character and t.Character:FindFirstChildOfClass("Humanoid")
	if not finalHumanoid or finalHumanoid.SeatPart ~= vehicleSeat then
		getgenv().MultiPrehistoricTwoMeterDone = false
		return
	end
	if workspace.Map:FindFirstChild("PrehistoricIsland") then
		return
	end

	if Settings["Auto Multi Find Prehistoric Island"] then
		AutoFindPrehistoric()
	end
end

function BuyMultiPrehistoricBoat()
	local remote = game:GetService("ReplicatedStorage").Remotes.CommF_
	pcall(function() remote:InvokeServer("BuyBoat", "Beast Hunter") end)
	task.wait(1.5)
	if not checkboat() then
		-- Sem Beast Hunter (indisponível/sem acesso): compra o Guardian.
		pcall(function() remote:InvokeServer("BuyBoat", "Guardian") end)
		pcall(function() A.CreateNoti({ Title = "Nexora Hub", Desc = "Beast Hunter indisponível - comprando Guardian", ShowTime = 4 }) end)
	end
end
function AutoFindPrehistoric()
	if
		not game:GetService("Workspace").Map:FindFirstChild("PrehistoricIsland")
		and not game:GetService("Players").LocalPlayer.PlayerGui.Main.TopHUDList.PrehistoricRaidTimer.Visible
		and not game:GetService("Players").LocalPlayer.PlayerGui.Main.TopHUDList.RaidTimer.Visible
	then
		getgenv().RespawnVolcano = true
		local g = checkboat()
		if not g or g and t:DistanceFromCharacter(g.VehicleSeat.Position) >= 4000 then
			local f = CFrame.new(-16204.0810546875, 9.0863618850708, 479.2259521484375)
			if (f.Position - t.Character.HumanoidRootPart.Position).Magnitude > 8 then
				if (f.Position - t.Character.HumanoidRootPart.Position).Magnitude > 1000 then
					if game:GetService("Players").LocalPlayer.Data.LastSpawnPoint.Value == "Tiki" then
						t.Character.Humanoid.Health = 0
						return
					end
				end
				toTarget(f)
			else
				if Settings["Auto Multi Find Prehistoric Island"] then BuyMultiPrehistoricBoat() else game:GetService("ReplicatedStorage").Remotes.CommF_:InvokeServer("BuyBoat", "PirateBrigade") end
				wait(3)
			end
		elseif t.Character.Humanoid.Sit then
			local f, R, m =
				CFrame.new(-118834.515625, 160, -78.9505844116211) * CFrame.new(0, 0, 99999999),
				CFrame.new(-32975.9921875, 160, 25963.7109375),
				if Settings["Will Back When over 10km"]
					then if DistanceFindLeviathan() >= 12000
						then true
						else if DistanceFindLeviathan() <= 4800 then false else false
					else false
			repeat
				task.wait(0.5)
				NoclipBoat(g)
				if Settings["Will Back When over 10km"] then
					m = if DistanceFindLeviathan() >= 10000
						then true
						else if DistanceFindLeviathan() <= 4800 then false else m
					if m then
						manageTween(g.VehicleSeat, R, 350, "TweenBoatBack")
					end
				end
				if not m or not Settings["Will Back When over 10km"] then
					manageTween(g.VehicleSeat, f, 350, "TweenBoat")
				end
			until not Settings["Auto Find Prehistoric Island"]
				and not Settings["Auto Multi Find Prehistoric Island"]
				or not t.Character.Humanoid.Sit
				or (game:GetService("Workspace").Map:FindFirstChild("PrehistoricIsland"))
			if getgenv().TweenBoat then
				getgenv().TweenBoat:Pause()
				getgenv().TweenBoat:Cancel()
			end
			if getgenv().TweenBoatBack then
				getgenv().TweenBoatBack:Pause()
				getgenv().TweenBoatBack:Cancel()
			end
		else
			if getgenv().TweenBoat then
				getgenv().TweenBoat:Pause()
				getgenv().TweenBoat:Cancel()
			end
			if getgenv().TweenBoatBack then
				getgenv().TweenBoatBack:Pause()
				getgenv().TweenBoatBack:Cancel()
			end
			toTarget(g.VehicleSeat.CFrame)
		end
	else
		if getgenv().RespawnVolcano and Settings["Webhook Find Prehistoric Island"] then
			getgenv().RespawnVolcano = false
			WebhookFindVolcano()
		end
		if getgenv().TweenBoat then
			getgenv().TweenBoat:Pause()
			getgenv().TweenBoat:Cancel()
		end
		A.CreateNoti({ Title = "Nexora Hub", Desc = "Prehistoric Island Spawned", ShowTime = 5 })
		if Settings["Auto Multi Find Prehistoric Island"] then
			Settings["Auto Multi Find Prehistoric Island"] = false
		else
			ToggleAutoFindPrehistoricIsland:SetStage(false)
		end
		wait(5)
	end
end
