function AreSelectedPlayersOnPrehistoricIsland()
	local island = workspace.Map:FindFirstChild("PrehistoricIsland")
	if not island or not island.Parent then
		return false
	end
	local selected = GetSelectedMultiPrehistoricPlayers()
	if #selected == 0 then
		return false
	end
	local islandCFrame, islandSize = island:GetBoundingBox()
	-- Pequena margem para não exigir que o jogador esteja exatamente dentro da borda.
	islandSize = islandSize + Vector3.new(20, 40, 20)
	local function isInsideIsland(player)
		local character = player and player.Character
		local root = character and character:FindFirstChild("HumanoidRootPart")
		if not root then
			return false
		end
		local localPos = islandCFrame:PointToObjectSpace(root.Position)
		return math.abs(localPos.X) <= islandSize.X / 2
			and math.abs(localPos.Y) <= islandSize.Y / 2
			and math.abs(localPos.Z) <= islandSize.Z / 2
	end
	for _, player in ipairs(selected) do
		if not isInsideIsland(player) then
			return false
		end
	end
	return true
end

function GoToPrehistoricIslandForMultiEvent()
	if not Settings["Auto Multi Event Prehistoric Island"] then
		return false
	end
	local island = workspace.Map:FindFirstChild("PrehistoricIsland")
	if not island or not island.Parent then
		return false
	end
	local character = t.Character
	local root = character and character:FindFirstChild("HumanoidRootPart")
	if not root then
		return false
	end
	local islandCFrame, islandSize = island:GetBoundingBox()
	local margin = Vector3.new(30, 60, 30)
	local checkSize = islandSize + margin
	local localPos = islandCFrame:PointToObjectSpace(root.Position)
	local onIsland = math.abs(localPos.X) <= checkSize.X / 2
		and math.abs(localPos.Y) <= checkSize.Y / 2
		and math.abs(localPos.Z) <= checkSize.Z / 2
	if onIsland then
		return true
	end

	-- Só pula quando realmente for iniciar o deslocamento para a ilha.
	-- É um único pulo para sair do barco; não repete enquanto procura a ilha.
	local humanoid = character:FindFirstChildOfClass("Humanoid")
	if humanoid and humanoid.SeatPart then
		if not getgenv().MultiPrehistoricEventJumped then
			getgenv().MultiPrehistoricEventJumped = true
			humanoid.Jump = true
			local jumpStart = tick()
			repeat
				task.wait()
			until not humanoid.SeatPart or tick() - jumpStart >= 2
		end
		if humanoid.SeatPart then
			return false
		end
	end

	-- O destino do Multi Event é a Relic Health da ilha: o CRÂNIO.
	-- Não usa o topo/centro do vulcão como destino.
	local relicHealthSkull = island:FindFirstChild("Skull", true)
	if not relicHealthSkull then
		local relic = island:FindFirstChild("PrehistoricRelic", true)
		if relic then
			relicHealthSkull = relic:FindFirstChild("Skull", true)
		end
	end

	local targetCFrame
	if relicHealthSkull then
		if relicHealthSkull:IsA("BasePart") then
			-- Fica ao lado/acima do crânio da Relic Health, sem ir para o topo do vulcão.
			targetCFrame = relicHealthSkull.CFrame * CFrame.new(0, 3, 10)
		elseif relicHealthSkull:IsA("Model") then
			targetCFrame = relicHealthSkull:GetPivot() * CFrame.new(0, 3, 10)
		end
	end

	if targetCFrame then
		if (root.Position - targetCFrame.Position).Magnitude > 20 then
			toTarget(targetCFrame)
		end
	else
		-- Se o crânio ainda não estiver disponível, não manda o jogador para o topo.
		return false
	end
	return false
end

function WaitForSelectedPlayersOnPrehistoricIsland()
	if not Settings["Auto Multi Event Prehistoric Island"] then
		return false
	end
	if not workspace.Map:FindFirstChild("PrehistoricIsland") then
		return false
	end
	local selected = GetSelectedMultiPrehistoricPlayers()
	if #selected == 0 then
		if not getgenv().MultiPrehistoricEventWaitingNoti or not getgenv().MultiPrehistoricEventWaitingNotiTime or tick() - getgenv().MultiPrehistoricEventWaitingNotiTime >= 5 then
			getgenv().MultiPrehistoricEventWaitingNoti = true
			getgenv().MultiPrehistoricEventWaitingNotiTime = tick()
			A.CreateNoti({ Title = "Nexora Hub", Desc = "Waiting for selected players to be selected", ShowTime = 5 })
		end
		return false
	end
	if not AreSelectedPlayersOnPrehistoricIsland() then
		if not getgenv().MultiPrehistoricEventWaitingNoti or not getgenv().MultiPrehistoricEventWaitingNotiTime or tick() - getgenv().MultiPrehistoricEventWaitingNotiTime >= 5 then
			getgenv().MultiPrehistoricEventWaitingNoti = true
			getgenv().MultiPrehistoricEventWaitingNotiTime = tick()
			A.CreateNoti({ Title = "Nexora Hub", Desc = "Waiting for selected players to arrive at Prehistoric Island...", ShowTime = 5 })
		end
		return false
	end
	if not getgenv().MultiPrehistoricEventStartedNoti then
		getgenv().MultiPrehistoricEventStartedNoti = true
		getgenv().MultiPrehistoricEventWaitingNoti = false
		getgenv().MultiPrehistoricEventWaitingNotiTime = nil
		A.CreateNoti({ Title = "Nexora Hub", Desc = "All selected players have arrived! Starting Auto Event Prehistoric Island...", ShowTime = 5 })
	end
	return true
end

function AutoAttackVolcano()
	if game:GetService("Workspace").Map:FindFirstChild("PrehistoricIsland") then
		if not t:GetAttribute("CurrentLocation") or t:GetAttribute("CurrentLocation") ~= "Prehistoric Island" then
			local g = DetectNpc("Fossil Expert")
			if g then
				toTarget(g.HumanoidRootPart.CFrame)
				return
			end
		end
		if DetectLava() then
			local g, f, R = next, workspace.Map.PrehistoricIsland:GetDescendants()
			for m, m in g, f, R do
				if m.Name == "TouchInterest" and m.Parent.Name ~= "TrialTeleport" then
					m:Destroy()
				end
			end
		end
		if #workspace.Map.PrehistoricIsland.Core.InteriorLava:GetChildren() > 0 then
			DeleteLava()
		end
		if
			not game:GetService("Players").LocalPlayer.PlayerGui.Main.TopHUDList.PrehistoricRaidTimer.Visible
			and not game:GetService("Players").LocalPlayer.PlayerGui.Main.TopHUDList.RaidTimer.Visible
		then
			if
				workspace.Map.PrehistoricIsland.Core:FindFirstChild("ActivationPrompt")
				and (workspace.Map.PrehistoricIsland.Core.ActivationPrompt:FindFirstChild("ProximityPrompt"))
			then
				toTarget(workspace.Map.PrehistoricIsland.Core.ActivationPrompt.CFrame)
				if t:DistanceFromCharacter(workspace.Map.PrehistoricIsland.Core.ActivationPrompt.Position) < 8 then
					fireproximityprompt(workspace.Map.PrehistoricIsland.Core.ActivationPrompt.ProximityPrompt, 1)
					wait(3)
				end
				return
			elseif
				not workspace.Map.PrehistoricIsland.Core:FindFirstChild("ActivationPrompt")
				and not workspace.Map.PrehistoricIsland.Core:FindFirstChild("FossilExpertSpawn")
			then
				local g = DetectNpc("Fossil Expert")
				if g then
					toTarget(g.HumanoidRootPart.CFrame)
					return
				end
			end
		else
			if b then
				local g = workspace.Map.PrehistoricIsland.Core.PrehistoricRelic.Skull
				repeat
					task.wait()
					toTarget(g.CFrame)
				until t:DistanceFromCharacter(g.Position) <= 200 or (DetectGolem()) or (DetectRockVolcano())
				b = false
				return
			end
			local g = DetectGolem()
			if g then
				repeat
					task.wait()
					toTarget(g.HumanoidRootPart.CFrame * CFrame.new(0, 20, 7))
					if Settings["Select Method Kill Golem"] == "Instant Kill [ Risk and can bug no die mob ]" then
						if t:DistanceFromCharacter(g.HumanoidRootPart.Position) < 50 then
							KillRaidEnemy()
						end
					else
						equiptool(NameWeapon(Settings["Select Weapon Kill Golem"] or "Melee"))
						getgenv().ClickM1Volcano(g)
					end
					if not getgenv().KillMobRaid and Settings["Kill Aura Only Raid And Volcano"] then
						getgenv().KillMobRaid = true
						local f = Settings["Time Delay Kill"] or 5
						g.Humanoid:ChangeState(Enum.HumanoidStateType.Dead)
						delay(f, function()
							getgenv().KillMobRaid = false
						end)
					end
				until not IsMobAlive(g) or not Settings["Auto Event Prehistoric Island"] and not Settings["Auto Multi Event Prehistoric Island"]
			end
			g = DetectRockVolcano()
			if g then
				if Settings["Fix Volcano Safe"] then
					local f = DetectPositionVolcano()
					local R, R = CheckPosnearRock(f, t.Character.HumanoidRootPart)
					if t:DistanceFromCharacter((CheckPosnearRock(f, g.WorldPivot))) >= 400 then
						s = R + 1
						if R >= 7 then
							s = 1
						end
						local R = f[s]
						toTarget(CFrame.new(R))
					else
						local f = X[math.floor(g.WorldPivot.Position.Y)]
						repeat
							task.wait()
							if t:DistanceFromCharacter((g.WorldPivot * f).Position) > 8 then
								toTarget(g.WorldPivot * f)
							end
							if t:DistanceFromCharacter(g.WorldPivot.Position) < 100 then
								AutoUseSkillFixLava()
							end
							getgenv().AimPos = g.WorldPivot
							local R = workspace.CurrentCamera
							G.Hit = g.WorldPivot
							G.Target = g
						until not g
							or not g.Parent
							or not Settings["Auto Event Prehistoric Island"] and not Settings["Auto Multi Event Prehistoric Island"]
							or not g.VFXLayer.Specs.Enabled
							or (DetectGolem())
						f = DetectGolem()
						if not f then
							b = true
						end
						wait(1)
					end
				else
					local f = X[math.floor(g.WorldPivot.Position.Y)]
					repeat
						task.wait()
						if t:DistanceFromCharacter((g.WorldPivot * f).Position) > 8 then
							toTarget(g.WorldPivot * f)
						end
						if t:DistanceFromCharacter(g.WorldPivot.Position) < 100 then
							AutoUseSkillFixLava()
						end
						getgenv().AimPos = g.WorldPivot
						local R = workspace.CurrentCamera
						G.Hit = g.WorldPivot
						G.Target = g
					until not g
						or not g.Parent
						or not Settings["Auto Event Prehistoric Island"] and not Settings["Auto Multi Event Prehistoric Island"]
						or not g.VFXLayer.Specs.Enabled
						or (DetectGolem())
					f = DetectGolem()
					if not f then
						b = true
					end
				end
			end
		end
	end
end
